import gc
import importlib.util
import json
import statistics
import sys
from pathlib import Path

import torch

from benchmarks.runners.compare_anthropic_a100 import fixture, elapsed, metadata
from miniworld_engine.integrations import a100_families as fam, token_dit_train as train
from miniworld_engine.integrations import conditioned_transition_sm80 as ct
from miniworld_engine.kernels import cuda_native as C
from miniworld_engine.kernels._nvcc import load_extension, host_flags, ensure_cuda_home

DEST = Path('/home/psk6950/miniworld-engine-scratch/codex_sol90')
spec = importlib.util.spec_from_file_location('old_families', DEST / 'families_before.py')
old = importlib.util.module_from_spec(spec)
spec.loader.exec_module(old)
ensure_cuda_home()
current_ext = C._ext()
old_ext = load_extension(name='a100_native_tails_before_sol90', sources=[str(DEST / 'rows_before.cu')],
    extra_cuda_cflags=[*host_flags(), '-O3', '-std=c++17', '-gencode=arch=compute_80,code=sm_80'], extra_cflags=['-O3', '-std=c++17'], verbose=False)
original = (C._ext, C._linear_bwd, train.serves, fam.triangle, fam.triangle_bidir)
ct_original = ct.serves


def old_linear_bwd(x, w, b, dy):
    xx, g = x.reshape(-1, x.shape[-1]), dy.reshape(-1, dy.shape[-1])
    return ((g @ w.to(g.dtype)).reshape(x.shape), (g.float().t() @ xx.float()).to(w.dtype),
            x.new_empty(0) if b is None else g.float().sum(0).to(b.dtype))


def old_serves(module, single, cond, pair, mask, compute_dtype=None):
    return cond.shape[0] == single.shape[0] and original[2](module, single, cond, pair, mask, compute_dtype)


def choose(key):
    if key == 'before':
        C._ext, C._linear_bwd, train.serves, fam.triangle, fam.triangle_bidir = (lambda: old_ext), old_linear_bwd, old_serves, old.triangle, old.triangle_bidir
        ct.serves = lambda m,x,c,dt,grad: ct._period(x,c,grad) is not None and ct_original(m,x,c,dt,grad)
    else:
        C._ext, C._linear_bwd, train.serves, fam.triangle, fam.triangle_bidir = original
        ct.serves = ct_original


def run(family, length, training):
    torch.manual_seed(191)
    torch.backends.cuda.matmul.allow_tf32 = False
    m, xs = fixture(family, length, 'miniworld')
    m = m.cuda().bfloat16().train(training)
    with torch.no_grad():
        for name, p in m.named_parameters():
            if p.ndim > 1: p.normal_(std=p.shape[-1] ** -.5)
            elif name.endswith('weight'): p.normal_(mean=1, std=.1)
            else: p.normal_(std=.1)
    for x in xs:
        if x.is_floating_point(): x.requires_grad_(training)
    dy = torch.randn_like(xs[0])
    def step():
        if training:
            m.zero_grad(set_to_none=True)
            for x in xs: x.grad = None
            y = m(*xs)
            y.backward(dy)
            return y
        with torch.no_grad(): return m(*xs)
    graphs, ys = {}, {}
    try:
        for key in ['before', 'after']:
            choose(key)
            stream = torch.cuda.Stream()
            stream.wait_stream(torch.cuda.current_stream())
            with torch.cuda.stream(stream):
                for _ in range(4): step()
            torch.cuda.current_stream().wait_stream(stream)
            torch.cuda.synchronize()
            g = torch.cuda.CUDAGraph()
            with torch.cuda.graph(g): ys[key] = step()
            graphs[key] = g
            g.replay()
        torch.cuda.synchronize()
        error = ((ys['after'].float()-ys['before'].float()).norm()/ys['before'].float().norm()).item()
        assert error < .008, error
        samples = {key: [] for key in graphs}
        for i in range(9):
            for key in (list(graphs) if i%2 == 0 else list(reversed(graphs))):
                samples[key].append(elapsed(graphs[key], 10, 1))
        row = {'family': family, 'length': length, 'training': training, 'hardware': metadata(),
               'times_ms': {k: statistics.median(v) for k,v in samples.items()}, 'samples_ms': samples,
               'speedup': statistics.median(a/b for a,b in zip(samples['before'], samples['after'])), 'output_error': error}
        (DEST / f'compare_{family}_{length}_{training}.json').write_text(json.dumps(row,indent=2,default=str)+'\n')
        print(family, length, training, row['times_ms'], row['speedup'], flush=True)
    finally: choose('after')
    del graphs, ys, m, xs
    gc.collect()
    torch.cuda.empty_cache()


for family in (sys.argv[1:] or ['dit_token', 'conditioned_transition', 'triattn_bidir_sa', 'triattn_bidir_bias', 'triattn_bias_start', 'triattn_bias_end']):
    for length in [128, 768]:
        for training in [False, True]: run(family, length, training)

